// One input format for every source: landing, Gmail, Fireflies, Gaius Meet, and later the CRM.
// brief = { source, segment?, role?, email?, client?, text?, hasText }
const SEGMENTS = ['law-firm', 'in-house', 'public-sector'];
const ROLES = ['champion', 'board'];
const input = $input.first().json;
const raw = input.body ?? input;
const pick = (v, allowed) => (allowed.includes(v) ? v : null);

const email = String(raw.email || '').trim().slice(0, 200);
const text = String(raw.text || raw.transcript || raw.notes || '').trim().slice(0, 60000);

// Without text we only guess the segment from the email domain. A weak signal: the AI overrides it when there is text.
const domain = email.split('@')[1]?.toLowerCase() || '';
const segmentFromDomain = /(^|\.)gov\.|\.gov$|gmina|powiat|urzad|um\.|ug\.|starostwo|(^|\.)bip\./.test(domain)
  ? 'public-sector'
  : /kancelaria|legal|law|lex|adwokat|radca|prawn/.test(domain) ? 'law-firm' : null;

return [{ json: {
  source: String(raw.source || 'landing'),
  segment: pick(raw.segment, SEGMENTS) ?? segmentFromDomain,
  role: pick(raw.role, ROLES),
  email: email || null,
  client: raw.client ? String(raw.client).slice(0, 200) : null,
  text,
  hasText: text.length > 0,
  receivedAt: new Date().toISOString(),
} }];

// The decisions: segment, decision-maker role, base offer and copy.
// Defaults (we know nothing): role = board, segment = in-house legal team.
const brief = $('Brief').first().json;
let ai = {};
try { ai = $('Analyze lead (AI)').first().json || {}; } catch (e) { ai = {}; }
if (ai.error) ai = {};

const SEGMENT_OK = ['law-firm', 'in-house', 'public-sector'];
const segment = [brief.segment, ai.segment].find((s) => SEGMENT_OK.includes(s)) ?? 'in-house';
const role = [brief.role, ai.role].find((r) => r === 'champion' || r === 'board') ?? 'board';

const SEGMENT = {
  'law-firm': { label: 'your law firm', tag: 'law-firm', who: 'Law firm' },
  'in-house': { label: 'your legal team', tag: 'legal-dept', who: 'In-house legal' },
  'public-sector': { label: 'your office', tag: 'public-sector', who: 'Public administration' },
}[segment];

const client = brief.client || ai.client || null;
const concerns = Array.isArray(ai.concerns) ? ai.concerns.slice(0, 3) : [];
return [{ json: {
  known: brief.hasText && !!ai.summary,
  segment, role, client,
  person: ai.person || null,
  country: ai.country || null,
  concerns,
  summary: ai.summary || null,
  tag: SEGMENT.tag,
  segmentLabel: SEGMENT.label,
  who: [ai.person, client, SEGMENT.who].filter(Boolean).join(' · '),
  baseOfferId: 'gaius-vault-base',
  offerName: `Offer for the ${role} · ${client || SEGMENT.who}`,
  brief: [ai.summary, concerns.length ? `Concerns: ${concerns.join('; ')}` : null,
          role === 'board' ? 'Read by the board: one accountable partner, budget, rollout plan.'
                           : 'Read by the champion: arguments for the team and for the board.'].filter(Boolean).join('\n'),
} }];

// One item = one PATCH request to Offer Studio.
const plan = $('Offer plan').first().json;
const offer = $input.first().json;
const segmentUseCases = $('Segment use cases').first().json.data || [];

// Which base-offer slides each reader sees.
const SHOW = {
  board:    ['cover', 'why', 'rollout', 'use-case', 'pricing', 'contact'],
  champion: ['cover', 'problems', 'what-is', 'use-case', 'comparison', 'why', 'pricing', 'contact'],
}[plan.role];

const COVER = plan.role === 'board'
  ? { subtitle: `**One accountable partner** for AI in ${plan.segmentLabel}`,
      lead: 'A rollout plan with named owners, a fixed monthly cost and a safe way to start.' }
  : { subtitle: 'A tool your team will **actually open on Monday**',
      lead: 'A demo script for your team and the arguments you take to the board.' };

const ops = [{ path: `/api/offers/${offer.id}`, body: { data: {
  origin: 'n8n-lead', client: plan.client, segment: plan.segment, role: plan.role,
  concerns: plan.concerns, summary: plan.summary,
} } }];

for (const s of offer.slides || []) {
  const patch = { hidden: !SHOW.includes(s.frame) };
  if (s.frame === 'cover') patch.data = COVER;
  if (s.frame === 'problems') patch.data = { title: `Where does the time of ${plan.segmentLabel} **go**?` };
  // Segment use cases only when the database has enough of them; otherwise all of them stay.
  if (s.frame === 'use-case' && segmentUseCases.length >= 3) {
    patch.block_ids = [];
    patch.query = { type: 'use_case', tag: plan.tag, limit: 6 };
  }
  ops.push({ path: `/api/slides/${s.id}`, body: patch });
}
return ops.map((json) => ({ json }));

const offer = $('Copy base offer').first().json;
const slide = (offer.slides || []).find((s) => s.frame === 'why');
return slide ? [{ json: { slideId: slide.id, brief: $('Offer plan').first().json.brief } }] : [];

const plan = $('Offer plan').first().json;
const offer = $('Copy base offer').first().json;
const started = new Date($('Brief').first().json.receivedAt).getTime();
return [{ json: {
  offerId: offer.id,
  offerName: offer.name,
  known: plan.known,
  segment: plan.segment,
  role: plan.role,
  who: plan.who,
  client: plan.client,
  concerns: plan.concerns,
  summary: plan.summary,
  pdfPath: `/webhook/offer-pdf?id=${encodeURIComponent(offer.id)}`,
  ms: Date.now() - started,
} }];

// For the hackathon the CRM write and the #sales alert are mocked. Connect the real nodes here.
const r = $input.first().json;
return [{ json: {
  crm: { stage: 'Offer', offerId: r.offerId, who: r.who, nextActivity: 'follow-up call in 2 days' },
  discord: { channel: '#sales', text: `New offer ready for ${r.who}. Offer Studio: ${r.offerId}` },
} }];
